FIRST_PERSON = {"俺", "私", "僕"}


def select(tokens, document):
    if document.get("metadata", {}).get("ndc") != "NDC 913":
        return
    for index, token in enumerate(tokens):
        if token.pos1 == "代名詞" and token.lemma in FIRST_PERSON:
            yield index, index + 1, "first_person"

GAP_POS1 = {"動詞", "助動詞", "補助記号"}
GAP_POS2 = {"格助詞", "係助詞", "接続助詞"}


def collocate_start(tokens, marker):
    start = marker - 1
    while start >= 0 and tokens[start].pos1 == "接尾辞" and tokens[start].pos2 == "名詞的":
        start -= 1
    if start >= 0 and tokens[start].pos1 in {"名詞", "代名詞"}:
        return start
    return None


def head_end(tokens, marker):
    index = marker + 1
    skipped = 0
    while (
        skipped < 5
        and index < len(tokens)
        and tokens[index].pos1 not in GAP_POS1
        and tokens[index].pos2 not in GAP_POS2
        and tokens[index].pos3 != "サ変可能"
    ):
        index += 1
        skipped += 1
    if index >= len(tokens):
        return None
    token = tokens[index]
    if token.pos1 == "動詞":
        return index + 1
    if (
        token.pos1 == "名詞"
        and token.pos3 == "サ変可能"
        and index + 1 < len(tokens)
        and tokens[index + 1].lemma == "為る"
    ):
        return index + 2
    return None


def select(tokens, document):
    for marker, token in enumerate(tokens):
        if token.surface != "を" or token.pos1 != "助詞" or token.pos2 != "格助詞":
            continue
        start = collocate_start(tokens, marker)
        end = head_end(tokens, marker)
        if start is not None and end is not None:
            yield start, end, "wo_collocation"

